window.DGNL_DE_MON = window.DGNL_DE_MON || {};
window.DGNL_DE_MON["l14"] = {"id": "l14", "ten": "Đề thi thử số 14", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "<i>“Trong tất cả các nữ sơn thần, nàng Echo<sup>1</sup> đẹp nhất. Nàng chỉ có một lỗi : nói nhiều quá. Nàng nói suốt ngày, và bất cứ về vấn đề gì Echo cũng là người nói tiếng sau cùng.</i><br><i>Một hôm, khi thần Zeus đang vui đùa cùng các nữ sơn thần, nữ thần Hera đột nhiên xuất hiện : Tất cả đều vội vã tản đi trừ nàng Echo. Nàng Echo bắt đầu trổ tài nói chuyện. Nữ thần Hera mải nghe chuyện nàng đến nỗi các nữ sơn thần đủ thì giờ trốn thoát.</i><br><i>Nhưng rồi Hera cũng biết là đã bị lừa bèn tức giận bảo Echo :</i><br><i>- Mi đừng hòng tái diễn trò đó, cái lưỡi có duyên của mi sẽ hết quyền lực. Từ giờ trở đi, mi không khua môi múa mỏ được nữa mà chỉ làm một việc là trả lời, chỉ trả lời thôi, không bao giờ mi được nói trước.”</i><br>(Thần thoại Hy Lạp)<br>Chú thích:<br><i>1. Echo: vừa là tên vị thần, vừa có nghĩa là tiếng vang</i><br>Đâu là nhận định đúng về đoạn trích trên?", "choices": ["Đoạn trích cho thấy không gian khởi nguyên khi vũ trụ chưa được tạo lập.", "Đoạn trích lí giải nguồn gốc của tiếng vang.", "Đoạn trích cho thấy các vị thần có cách cư xử cao thượng, công bằng.", "Các vị thần trong đoạn trích không có những cảm xúc như con người."], "correctIndex": 1, "explain": "<b>Câu 1. Chọn B.</b> <b>Giải thích:</b> Đoạn trích kể về việc nàng Echo bị nữ thần Hera trừng phạt, khiến nàng không thể tự nói trước mà chỉ có thể lặp lại lời người khác. Đây là cách thần thoại Hy Lạp hư cấu để lí giải hiện tượng âm thanh phản xạ (tiếng vang)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu là phương án chứa ca dao có thái độ khác những phương án còn lại?", "choices": ["“Cái cò lặn lội bờ ao,<br>Hỡi cô yếm đào lấy chú tôi chăng?<br>Chú tôi hay tửu, hay tăm,<br>Hay nước chè đặc, hay nằm ngủ trưa.<br>Ngày thì ước những ngày mưa,<br>Đêm thì ước những đêm thừa trống canh.”", "“Gỗ trắc đem lót ván cầu,<br>Yến sào đem nấu với đầu cá rô.”", "“Khi xưa vác bút theo thầy,<br>Bây giờ em lại vác cày theo trâu.”", "“Áo anh sứt chỉ đường tà,<br>Vợ anh chưa có, mẹ già chưa khâu.<br>Áo anh sứt chỉ đã lâu,<br>Mai mượn cô ấy về khâu cho cùng.”"], "correctIndex": 3, "explain": "<b>Câu 2. Chọn D. Giải thích: Các phương án A, B, C đều là những câu ca dao có tính chất châm biếm, mỉa mai hoặc than thân trách phận (châm biếm thói lười biếng, sự kệch cỡm, hoặc cảnh ngộ đổi thay). Riêng phương án D là bài ca dao giao duyên, thể hiện tình cảm và lời ướm hỏi chân thành, tế nhị của chàng trai.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Họ lạc lối giữa u sầu mù mịt,</i><br><i>Những người si theo dõi dấu chân yêu;</i><br><i>Và cảnh đời là sa mạc cô liêu.</i><br><i>Và tình ái là sợi dây vấn vít.</i><br><i>Yêu, là chết ở trong lòng một ít.”</i><br>(Dại khờ, Xuân Diệu)<br>Dòng nào chứa những biện pháp tu từ có trong đoạn thơ trên?", "choices": ["Điệp từ, lặp cấu trúc, liệt kê, so sánh", "Điệp từ, lặp cấu trúc, nhân hoá, điệp vần", "Điệp từ, liệt kê, so sánh, nghịch ngữ", "Điệp từ, lặp cấu trúc, nhân hoá, điệp vần, so sánh"], "correctIndex": 0, "explain": "<b>Câu 3. Chọn A. Giải thích: Đoạn thơ sử dụng các biện pháp: Điệp từ (“Và”, “Yêu”), lặp cấu trúc (“Và... là...”), liệt kê (“u sầu mù mịt”, “sa mạc cô liêu”, “sợi dây vấn vít”) và so sánh (“cảnh đời là sa mạc”, “tình ái là sợi dây”).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Vợ Ðiền khổ, con Ðiền khổ, cha mẹ Ðiền khổ. Chính Ðiền cũng khổ. Bao nhiêu người nữa, cùng một cảnh, khổ như Ðiền! Cái khổ làm héo một phần lớn những tính tình tươi đẹp của người ta. Tiếng đau khổ vang dội lên mạnh mẽ. Chao ôi! Chao ôi! Nghệ thuật không cần là ánh trăng lừa dối, nghệ thuật có thể chỉ là tiếng đau khổ kia, thoát ra từ những kiếp lầm than, vang dội lên mạnh mẽ trong lòng Ðiền. Ðiền chẳng cần đi đâu cả. Ðiền chẳng cần trốn tránh, Ðiền cứ đứng trong lao khổ, mở hồn ra đón lấy tất cả những vang động của đời... </i>(Giăng sáng, Nam Cao)<br>Đâu không phải là tác dụng của biện pháp liệt kê kết hợp với lặp cấu trúc trong đoạn văn trên?", "choices": ["Nhấn mạnh sự lan rộng, chồng chất của nỗi khổ, từ đó làm nổi bật sự thức tỉnh của Điền trước hiện thực đời sống.", "Tạo nhịp văn dồn dập, góp phần diễn tả sức vang động mạnh mẽ của nỗi đau trong tâm hồn Điền.", "Cho thấy cái khổ không còn là nỗi đau cá nhân mà trở thành hiện thực phổ quát của nhiều kiếp người lầm than.", "Khắc họa sự quẩn quanh, bế tắc của Điền, khiến nhân vật chỉ còn muốn thoát li khỏi đời sống nghèo khổ."], "correctIndex": 3, "explain": "<b>Câu 4. Chọn D. Giải thích: Biện pháp liệt kê và lặp cấu trúc ở đây nhằm nhấn mạnh sự thức tỉnh và mở lòng của nhân vật Điền trước nỗi đau nhân thế, không phải để khắc họa sự bế tắc hay muốn thoát li đời sống.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "NGUYỄN TRÃI: - Tôi nghĩ, có lẽ phải từ đốm nhỏ mà mở dẫn ra như vết dầu loang. Không nên vội tính chuyện đánh thành, mà có lẽ trước tiên phải biết đánh vào lòng người, lòng dân ta và cả quân địch nữa! Chịu nhịn đói để dân có cái ăn, chịu xả thân để dân còn được sống, nói cho cùng, ở đâu rõ nhân nghĩa thì lòng người hướng về đấy. Sao cho dân ta mọi nơi ngóng trông, mà bên địch thì nó phân vân, chần chừ, khó quyết. Cách dùng binh thì đừng ham dàn quân đối mặt với nó. Phải tỉa nó trước, khoét nó sau. Lấy yếu chống mạnh, đánh bất ngờ. Lấy ít đánh nhiều, dùng mai phục. Đừng chê nhỏ, đừng vội tham to, giấu tung tích cho kín, hiện đằng đông mà đánh đằng tây, góp gió thành bão, vừa đánh vừa gây dựng, từ nhiều suối nhỏ mà dần họp thành sông lớn.<br>TRẦN NGUYÊN HÃN: - Sao ông nhìn thấy được như vậy!<br>NGUYỄN TRÃI: - Nói thì dễ, ông ạ. Chỉ có nói thì chưa động được đến sợi lông chân của nó.<br>TRẦN NGUYÊN HÃN: - Nhưng mà tìm ra đúng sai cho sáng rõ thì không dễ chút nào. Có khi dám lăn vào lửa, mà mở mắt nhìn vào cái thật. Nghe ông mà tôi vẫn còn bàng hoàng cả người!<br>(Nguyễn Trãi ở Đông Quan, Nguyễn Đình Thi)<br>Đâu là nhận định đúng về đoạn trích trên?", "choices": ["Đoạn trích thể hiện tư tưởng nhân nghĩa của Nguyễn Trãi khi ông đặt việc thu phục lòng người lên trước việc công thành.", "Đoạn trích cho thấy Nguyễn Trãi chủ trương tạm gác nhân nghĩa để ưu tiên mưu lược quân sự, vì trong hoàn cảnh chiến tranh, thắng lợi trước mắt quan trọng hơn việc giữ lòng dân.", "Đoạn trích khắc họa Nguyễn Trãi như một con người thiên về lí tưởng đạo đức, nhưng còn thiếu niềm tin vào khả năng hành động thực tế của chiến lược do mình đề xuất.", "Đoạn trích nhấn mạnh sự sắc sảo của Nguyễn Trãi trong việc dùng mưu kế đánh lừa quân địch, từ đó xem binh pháp là con đường quyết định thắng lợi."], "correctIndex": 0, "explain": "<b>Câu 5. Chọn A. Giải thích: Lời thoại của Nguyễn Trãi nhấn mạnh việc &quot;đánh vào lòng người&quot;, &quot;để dân có cái ăn&quot;, &quot;để dân còn được sống&quot; và khẳng định &quot;ở đâu rõ nhân nghĩa thì lòng người hướng về đấy&quot;. Điều này minh chứng cho tư tưởng nhân nghĩa cốt lõi của ông.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Hình ảnh biển nào trong các phương án sau là hình ảnh siêu thực?", "choices": ["Anh không xứng là biển xanh<br>Nhưng anh muốn em là bờ cát trắng<br>Bờ cát dài phẳng lặng<br>Soi ánh nắng pha lê... (Biển, Xuân Diệu)", "Máu tim ta tuôn ra làm biển cả,<br>Mà sóng lòng dồn dập như mây trôi.<br>Sóng lòng ta tràn lan ngoài xứ lạ<br>Dâng cao lên, cao tột tới trên trời. (Biển hồn ta, Hàn Mặc Tử)", "Trưa kim cương biển choá hồn ta<br>Nước long lanh xuống tự Thiên hà.<br>Giờ gương mỏng đất trời tự ngắm<br>Biển yêu trời giao cảm bao la (Biển, Huy Cận)", "Cha tra vào đáy biển<br>Cho con he, con nục, con hồng sinh tụ<br>Như những chùm trái bưởi, trái bòng<br>Và trên nóc mái nhà kỳ ảo<br>Cha bủa tung vàng lưới mênh mông (Biển trước mặt - Biển, Nguyễn Khoa Điềm)"], "correctIndex": 1, "explain": "<b>Câu 6. Chọn B. Giải thích: Hình ảnh &quot;Máu tim ta tuôn ra làm biển cả&quot; và &quot;Sóng lòng... dâng cao lên... tới trên trời&quot; là những hình ảnh siêu thực, vượt ra khỏi logic vật lí thông thường để diễn tả cảm xúc mãnh liệt của cái tôi cá nhân.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đọc bài thơ sau và trả lời câu hỏi<br><table class=\"bang-de\"><tr><td><b>Bài thơ (Đăng cao – 杜甫 / Đỗ Phủ)</b></td><td><b>Bản dịch nghĩa</b></td></tr><tr><td>Phong cấp, thiên cao, viên khiếu ai,<br>Chử thanh, sa bạch, điểu phi hồi.<br>Vô biên lạc mộc tiêu tiêu há,<br>Bất tận trường giang cổn cổn lai.<br>Vạn lý bi thu thường tác khách,<br>Bách niên đa bệnh độc đăng đài.<br>Gian nan khổ hận phồn sương mấn,<br>Lạo đảo tân đình trọc tửu bôi.</td><td>Gió thổi gấp, trời cao, vượn kêu buồn,<br>Bến nước trong, cát trắng, chim bay lượn vòng.<br>Vô vàn lá xào xạc rụng xuống,<br>Dòng sông dài cuồn cuộn chảy vô tận.<br>Xa nhà vạn dặm, vẻ thu hiu hắt, mãi vẫn làm khách xứ người,<br>Cuộc đời lắm bệnh, một mình lên đài cao.<br>Gian nan, khổ hận, tóc mai dày nhuốm màu sương gió,<br>Thân già ốm yếu nên mới phải thôi cạn chén rượu đục.</td></tr></table><br>Cảm hứng chủ đạo của bài thơ là gì?", "choices": ["Nỗi buồn trước cảnh thu thấm đẫm cảm thức lưu lạc, bệnh tật, cô độc và nỗi đau thời thế của con người nơi đất khách.", "Nỗi buồn trước cảnh thu rộng lớn, hiu hắt, bắt nguồn từ sự tàn phai của thiên nhiên và dòng chảy vô tận của thời gian.", "Nỗi cô đơn của con người khi một mình lên cao, đối diện với không gian mênh mông và nhận ra sự nhỏ bé của kiếp người.", "Nỗi đau của kẻ sĩ trước cảnh đời gian nan, trong đó bệnh tật và tuổi già khiến con người không còn khả năng hưởng thú thanh nhàn."], "correctIndex": 0, "explain": "<b>Câu 7. Chọn A. Giải thích: Bài thơ Đăng cao thể hiện nỗi buồn tổng hòa của Đỗ Phủ: sự rệu rã của tuổi già, bệnh tật, kiếp sống lưu lạc nơi đất khách và nỗi đau trước cảnh nước nhà loạn lạc (thời thế).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“<i>Từ phen </i><b><i>đá biết tuổi vàng</i></b><i>,</i><br><i>Tình càng thấm thía, dạ càng ngẩn ngơ.” </i>(Truyện Kiều, Nguyễn Du)<br>Cụm từ in đậm có nghĩa là gì?", "choices": ["Sau khi trò chuyện, hai con người mới hiểu nhau và yêu thương nhau hơn.", "Đá hóa thành vàng tượng trưng cho sự biến đổi kì diệu của số phận.", "Khi tuổi trẻ qua đi, con người mới nhận ra vẻ đẹp quý giá của tình yêu.", "Từ khi lời thề son sắt được chứng giám, tình cảm càng trở nên sâu nặng."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án D, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b>Câu 8. Chọn D. Giải thích: &quot;Đá biết tuổi vàng&quot; là cách nói ẩn dụ cho việc lời thề nguyền son sắt (đá) đã qua thử thách thời gian (vàng), ý chỉ từ khi hai người thề bồi, đính ước, tình cảm càng trở nên sâu đậm.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Mọi tên tuổi vinh dự chỉ hư danh</i><br><i>Chẳng nghĩa lý bằng chiều nay em nhóm bếp</i><br><i>Phiên chợ xanh non màu rau diếp</i><br><i>Tiếng trẻ cười, tiếng chim hót xa xa.</i><br><i>Buồn làm chi, này đây những bông hoa</i><br><i>Hoa trong trắng hiểu rõ lòng anh lắm</i><br><i>Như kẻ đi xa vứt áo choàng bụi bặm</i><br><i>Anh trở về nhà tắm nước giếng trong.</i><br>(Không đề, Lưu Quang Vũ)<br>Ý nghĩa nào sau đây đúng nhất với nội dung bài thơ?", "choices": ["Bài thơ thể hiện sự tỉnh thức của con người trước sự mong manh của danh vọng, hướng về những giá trị đời thường có khả năng nâng đỡ tâm hồn.", "Bài thơ bộc lộ niềm tin rằng tình yêu và mái ấm gia đình có thể giúp con người gột rửa những mệt mỏi, bụi bặm sau hành trình đời sống.", "Bài thơ cho thấy sự đối lập giữa hư danh bên ngoài và vẻ trong trẻo của đời sống thường nhật, qua đó phê phán sự phù phiếm của công danh.", "Bài thơ diễn tả khát vọng trở về với đời sống bình dị - con người được giải toả áp lực trong tình yêu, thiên nhiên và những sinh hoạt quen thuộc."], "correctIndex": 0, "explain": "<b>Câu 9. Chọn A. Giải thích: Bài thơ đối lập &quot;hư danh&quot; với những hình ảnh bình dị như &quot;nhóm bếp&quot;, &quot;rau diếp&quot;, &quot;tiếng trẻ cười&quot;. Qua đó, tác giả khẳng định sự tỉnh thức, trân trọng những giá trị đời thường thuần khiết.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<i>Về đến nhà thì cũng đã mệt rã rời. Tuyền dù có tắm nước lạnh, uống trà dược thảo, bật cả hai bóng đèn cho sáng loà cái phòng con, thì cũng không thức được. Tuyền chui vào giường, tự nhủ, thì đi ngủ. Mình sẽ chỉ như thế này hai năm nữa thôi, rồi sau đó sẽ chỉ làm những gì mình thích, còn bây giờ thì ngủ. </i>(Có con, Phan Thị Vàng Anh)<br>Đâu là nhận định đúng về người kể trong đoạn trích trên?", "choices": ["Đây là người kể ngôi thứ nhất", "Đây là người kể ngôi thứ ba hạn tri", "Đây là người kể ngôi thứ ba toàn tri", "Đây là người kể ngôi thứ hai."], "correctIndex": 1, "explain": "<b>Câu 10. Chọn B. Giải thích: Người kể chuyện xưng &quot;Tuyền&quot; (ngôi thứ ba), nhưng chỉ tập trung miêu tả suy nghĩ, cảm xúc và cái nhìn từ phía nhân vật Tuyền chứ không thấu suốt mọi nhân vật khác, nên đây là ngôi thứ ba hạn tri.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn từ mà nghĩa của nó không cùng nghĩa với nhóm từ còn lại", "choices": ["kế hoạch", "chiến lược", "sách lược", "yêu sách"], "correctIndex": 3, "explain": "<b>Câu 11. Chọn D. Giải thích: &quot;Kế hoạch&quot;, &quot;chiến lược&quot;, &quot;sách lược&quot; đều chỉ các phương án, cách thức để đạt mục tiêu. &quot;Yêu sách&quot; mang nghĩa là những đòi hỏi quá đáng, không cùng nhóm nghĩa về phương châm hành động.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa từ, cụm từ đúng chính tả", "choices": ["cộc cằn, cha già con cọc, dậm chân", "cọc cằn, cha già con cộc, giậm chân", "cộc cằn, cha già con cọc, giậm chân", "cọc cằn, cha già con cọc, giậm chân"], "correctIndex": 2, "explain": "<b>Câu 12. Chọn C. </b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn câu không mắc lỗi dùng từ.", "choices": ["Anh rất thủ cựu vì chỉ biết giữ lấy lối tư duy vấn đề rất cũ kĩ.", "Bản tình ca bất hữu ấy đã mang lại cho tôi một cảm xúc khó tả.", "Chúng tôi cùng đồng loạt phản đối chính sách mới.", "“Hoàng thiên bất phụ độc thư nhân” có nghĩa là ông trời không phụ người đọc sách."], "correctIndex": 3, "explain": "<b>Câu 13. Chọn D. Giải thích: Câu D đúng cả về ngữ pháp lẫn ngữ nghĩa. Câu A lặp từ (thủ cựu đã bao hàm ý cũ kĩ), câu B viết sai chính tả (bất hủ chứ không phải bất hữu), câu C thừa từ (đã &quot;cùng&quot; thì không cần &quot;đồng loạt&quot;).</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Thấy nước sông mỗi lúc một dâng lên cao khiến cho dân làng lo sợ.<br>Đây là câu mắc lỗi gì?", "choices": ["Lỗi ngữ pháp", "Lỗi chính tả", "Lỗi logic", "Lỗi mơ hồ"], "correctIndex": 0, "explain": "<b>Câu 14. Chọn A. Giải thích: Câu này mắc lỗi thiếu chủ ngữ. &quot;Thấy...&quot; biến cả cụm từ phía sau thành trạng ngữ hoặc bổ ngữ, khiến câu không có chủ thể thực hiện hành động.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Hôm thi đỗ, ba tôi dặn tôi phải biết khiêm tốn.<br>Đây là câu mắc lỗi gì?", "choices": ["Lỗi ngữ pháp", "Lỗi quy chiếu", "Lỗi dùng từ", "Lỗi logic"], "correctIndex": 1, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án C, còn đáp án tô trong đề là B — web đang dùng B.)</i><br><b>Câu 15. Chọn C. Giải thích: Lỗi dùng từ &quot;khiêm tốn&quot; chưa phù hợp trong văn cảnh này; thường dùng từ &quot;khiêm nhường&quot; hoặc cách diễn đạt khác sẽ tự nhiên hơn, hoặc xét theo logic thì việc &quot;thi đỗ&quot; và &quot;khiêm tốn&quot; không phải là quan hệ nhân quả trực tiếp bắt buộc.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn phương án chứa những từ bào đồng âm.", "choices": ["chiến bào, long bào, áo bào", "bào mòn, long bào, bào tử", "chiến bào, long bào, bào mòn", "bào mòn, bào tử, tế bào"], "correctIndex": 1, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án C, còn đáp án tô trong đề là B — web đang dùng B.)</i><br><b>Câu 16. Chọn C. Giải thích: &quot;Chiến bào&quot;, &quot;long bào&quot; (áo) và &quot;bào mòn&quot; (làm mòn dần) là các từ đồng âm (phát âm giống nhau nhưng nghĩa khác nhau hoàn toàn). Các phương án khác chứa các từ có gốc &quot;bào&quot; mang nghĩa liên quan đến tế bào/sinh học.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Máy tính có thể thực hiện nhiều ______ cùng lúc.<br>Chọn từ phù hợp nhất điền vào chỗ trống.", "choices": ["tác vụ", "tác nhân", "tác hợp", "tác động"], "correctIndex": 0, "explain": "<b>Câu 17. Chọn A. Giải thích: Trong thuật ngữ tin học, &quot;tác vụ&quot; (task) là từ dùng để chỉ một công việc hay một chương trình mà máy tính đang thực hiện.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Thành ngữ nào không cùng cấu trúc với những thành ngữ còn lại?", "choices": ["máu chảy ruột mềm", "môi hở răng lạnh", "áo gấm đi đêm", "bút sa gà chết"], "correctIndex": 2, "explain": "<b>Câu 18. Chọn C. Giải thích: Các câu A, B, D đều có cấu trúc đối (máu chảy - ruột mềm; môi hở - răng lạnh; bút sa - gà chết). Câu C &quot;áo gấm đi đêm&quot; có cấu trúc Cụm danh từ - Động từ, không có tính chất đối xứng giữa hai vế.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Nhận định nào sau đây đúng nhất về văn học trung đại Việt Nam?", "choices": ["Thể hiện tư tưởng đạo lí truyền thống, đồng thời bước đầu bộc lộ cái tôi cá nhân trong những giới hạn nhất định.", "Chủ yếu đề cao cái tôi cá nhân và khát vọng tự do, giải phóng con người khỏi mọi ràng buộc xã hội.", "Tập trung phản ánh đời sống hiện thực với cái nhìn khách quan, phê phán trực diện các vấn đề xã hội.", "Hoàn toàn tuân thủ tính quy phạm về nội dung và hình thức, không có sự vận động hay biến đổi."], "correctIndex": 0, "explain": "<b>Câu 19. Chọn A. Giải thích: Văn học trung đại Việt Nam mang tính quy phạm, đề cao đạo lí (&quot;văn dĩ tải đạo&quot;) nhưng ở giai đoạn sau (thế kỉ XVIII - XIX) đã bắt đầu thể hiện cái tôi cá nhân sâu sắc qua các tác phẩm của Nguyễn Du, Hồ Xuân Hương...</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Đêm khuya văng vẳng trống canh dồn,</i><br><i>Trơ cái hồng nhan với nước non.</i><br><i>Chén rượu hương đưa say lại tỉnh,</i><br><i>Vầng trăng bóng xế khuyết chưa tròn,</i><br><i>Xiên ngang mặt đất, rêu từng đám.</i><br><i>Đâm toạc chân mây, đá mấy hòn.</i><br><i>Ngán nỗi xuân đi xuân lại lại,</i><br><i>Mảnh tình san sẻ tí con con!</i><br>(Tự tình II)<br>Nhận định nào sau đây đúng về niêm của bài thơ trên?", "choices": ["Câu 1 niêm với câu 8, câu 2 niêm với câu 3, câu 4 niêm với câu 5, câu 6 niêm với câu 7.", "Câu 1 niêm với câu 2, câu 3 niêm với câu 4, câu 5 niêm với câu 6, câu 7 niêm với câu 8.", "Câu 1 niêm với câu 3, câu 2 niêm với câu 4, câu 5 niêm với câu 7, câu 6 niêm với câu 8.", "Câu 1 niêm với câu 4, câu 2 niêm với câu 5, câu 3 niêm với câu 6, câu 7 niêm với câu 8."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án C, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b>Câu 20. Chọn C. Giải thích: Theo quy tắc niêm của thơ Đường luật: Câu 1 niêm với 8, 2 niêm với 3, 4 niêm với 5, 6 niêm với 7.</b>"}], "khongXaoTron": true}, {"noiDungChung": "Báo cáo tóm nêu lên nhiều hình thức bạo lực mà học sinh phải đối mặt trong và xung quanh trường học. Theo số liệu mới nhất từ UNICEF:<br>Trên toàn cầu, cứ 3 em học sinh trong độ tuổi 13-15 thì có hơn 1 em từng bị bắt nạt, và tỷ lệ học sinh tham gia đánh nhau cũng gần như vậy.<br>Cứ 10 sinh viên tại 39 quốc gia công nghiệp thì có 3 em thừa nhận đã từng bắt nạt bạn.<br>Năm 2017, đã có 396 vụ tấn công tại trường học được ghi nhận hoặc được xác nhận ở Cộng hòa Dân chủ Công-gô, 26 vụ ở Nam Sudan, 67 vụ tại Cộng hòa Ả Rập Syria và 20 vụ tại Yemen.<br>Gần 720 triệu trẻ em trong độ tuổi đi học sống ở các quốc gia nơi mà trừng phạt thân thể trong nhà trường không bị cấm.<br>Tuy trẻ em gái và bé trai có nguy cơ bị bắt nạt như nhau, nhưng các bé gái có nhiều khả năng trở thành nạn nhân của các hình thức bắt nạt tâm lý hơn còn các bé trai có nguy cơ bị bạo lực và đe dọa về thể chất.<br>Báo cáo cũng ghi nhận rằng bạo lực liên quan đến sử dụng vũ khí trong trường học, chẳng hạn như dao và súng, vẫn tiếp tục xảy ra và cướp đi nhiều sinh mạng. Báo cáo cũng cho biết trong một thế giới kỹ thuật số ngày càng gia tăng, những kẻ chuyên đi bắt nạt đang phổ biến nội dung bạo lực, gây tổn thương và xúc phạm người khác chỉ với một cái nhấp chuột.<br>Báo cáo cũng cho thấy ở nhiều khu vực của Campuchia, Indonesia, Nepal và Việt Nam, nơi các học sinh mô tả trường học của mình là không an toàn, các yếu tố phổ biến nhất khiến các em đưa ra nhận định đó là do các em phải chịu ngôn ngữ mang tính nhục mạ, đánh nhau và bị các học sinh khác quấy rối. Số liệu cho thấy bắt nạt là hình thức bạo lực phổ biến nhất trong nhà trường. Bắt nạt và đánh nhau rõ ràng là hiện tượng bạo lực giữa các bạn cùng trang lứa trong trường học đang trở nên báo động.<br>Phân tích số liệu từ Ethiopia, Ấn Độ, Peru và Việt Nam cho thấy bạo lực trong trường học - bao gồm cả xâm hại thể chất và lời nói của giáo viên và các học sinh khác - là lý do phổ biến nhất khiến trẻ em không thích đi học. Và việc không thích đi học có tác động rất lớn dẫn tới điểm môn toán thấp hơn, tính tự giác và lòng tự trọng cũng bị ảnh hưởng.<br>Để chấm dứt bạo lực học đường, UNICEF và các đối tác kêu gọi hành động khẩn cấp trong các lĩnh vực sau:<br>Thực hiện chính sách và pháp luật để bảo vệ học sinh khỏi bạo lực học đường.<br>Tăng cường các biện pháp phòng ngừa và ứng phó trong trường học.<br>Thúc đẩy các cộng đồng và cá nhân tham gia cùng học sinh lên tiếng về bạo lực và cùng nỗ lực thay đổi văn hóa trong lớp học và trong cộng đồng.<br>Đầu tư hiệu quả hơn và cụ thể vào những giải pháp đã được chứng minh có thể giúp đảm bảo an toàn cho học sinh và nhà trường.<br>Thu thập số liệu tốt hơn, và có số liệu phân tổ về bạo lực đối với trẻ em trong và xung quanh nhà trường đồng thời chia sẻ phương pháp hiệu quả.<br>(Theo UNICEF, một nửa thanh thiếu niên trên thế giới bị bạo lực học đường, Nguyễn Thị Thanh Hương)", "cauHoi": [{"question": "Theo đoạn trích, hình thức bạo lực phổ biến nhất trong nhà trường là gì?", "choices": ["Tấn công bằng vũ khí", "Trừng phạt thân thể từ giáo viên", "Bắt nạt", "Quấy rối ngoài nhà trường"], "correctIndex": 2, "explain": "<b>Câu 21. Chọn C. Giải thích: Văn bản nêu rõ: &quot;Số liệu cho thấy bắt nạt là hình thức bạo lực phổ biến nhất trong nhà trường.&quot;</b>"}, {"question": "Văn bản trên chủ yếu trình bày thông tin theo cách nào?", "choices": ["Theo trình tự thời gian từ thực trạng đến tương lai", "Theo quan hệ nguyên nhân - kết quả", "Nêu thực trạng, hậu quả và đề xuất giải pháp", "So sánh giữa bạo lực học đường ở các châu lục"], "correctIndex": 2, "explain": "<b>Câu 22. Chọn C. Giải thích: Cấu trúc bài báo cáo đi từ việc đưa ra các con số thực trạng bạo lực, nêu lên hậu quả đối với học sinh và cuối cùng là các kiến nghị của UNICEF để giải quyết vấn đề.</b>"}, {"question": "Chi tiết nào dưới đây cho thấy đoạn trích không chỉ đề cập đến bạo lực trực tiếp trong nhà trường mà còn mở rộng tới những hình thức bạo lực có tính chất gián tiếp hoặc mang tính tâm lí?", "choices": ["Năm 2017, đã có 396 vụ tấn công tại trường học được ghi nhận hoặc được xác nhận ở Cộng hòa Dân chủ Công-gô.", "Gần 720 triệu trẻ em trong độ tuổi đi học sống ở các quốc gia nơi mà trừng phạt thân thể trong nhà trường không bị cấm.", "Các yếu tố phổ biến khiến học sinh mô tả trường học không an toàn là ngôn ngữ mang tính nhục mạ, đánh nhau và bị các học sinh khác quấy rối.", "Cứ 10 sinh viên tại 39 quốc gia công nghiệp thì có 3 em thừa nhận đã từng bắt nạt bạn."], "correctIndex": 2, "explain": "<b>Câu 23. Chọn C. Giải thích: Việc nhắc đến &quot;ngôn ngữ mang tính nhục mạ&quot; và &quot;quấy rối&quot; chính là các hình thức bạo lực tâm lí/gián tiếp, khác với bạo lực thể xác trực tiếp như đánh nhau hay dùng vũ khí.</b>"}, {"question": "Việc sử dụng dày đặc các số liệu và dẫn chứng quốc gia trong đoạn trích có tác dụng nổi bật nhất là gì?", "choices": ["Làm cho vấn đề bạo lực học đường hiện lên như một hiện tượng có tính toàn cầu, đa dạng biểu hiện và đáng báo động.", "Khẳng định bạo lực học đường chủ yếu xảy ra ở các nước nghèo hoặc đang có xung đột.", "Chứng minh rằng bắt nạt trên mạng nguy hiểm hơn hẳn mọi hình thức bạo lực khác trong trường học.", "Tạo giọng điệu tranh biện nhằm phê phán trực tiếp trách nhiệm của giáo viên và phụ huynh."], "correctIndex": 0, "explain": "<b>Câu 24. Chọn A. Giải thích: Các số liệu từ nhiều quốc gia (Việt Nam, Ethiopia, Syria, Yemen...) giúp người đọc nhận thấy đây là một vấn đề nhức nhối mang tính quy mô toàn cầu.</b>"}, {"question": "Đâu là nhận định không phù hợp với nội dung đoạn trích?", "choices": ["Bạo lực học đường là vấn đề đang diễn ra ở nhiều quốc gia và dưới nhiều hình thức khác nhau.", "Bắt nạt và đánh nhau là những biểu hiện đáng báo động của bạo lực giữa bạn cùng trang lứa trong trường học.", "Chỉ những quốc gia đang có chiến tranh mới đối mặt với tình trạng bạo lực học đường nghiêm trọng.", "UNICEF kêu gọi cần có chính sách, giải pháp trong nhà trường và sự tham gia của cộng đồng để chấm dứt bạo lực học đường."], "correctIndex": 2, "explain": "<b>Câu 25. Chọn C. Giải thích: Văn bản cho thấy bạo lực học đường xảy ra ở cả các quốc gia công nghiệp (39 nước) và các quốc gia hòa bình, không chỉ riêng vùng chiến sự.</b>"}], "khongXaoTron": true}, {"noiDungChung": "Trong thời đại toàn cầu hóa hiện nay, vấn đề phẩm chất dân tộc trong văn học trở thành một vấn đề nóng bỏng, mang tính thời sự. Thật ra, từ bao đời nay, khi thực thể dân tộc hình thành, không một nhà văn lớn nào lại không gắn bó với dân tộc và đất nước đã khai sinh ra mình. Người ta gắn bó với những bước thăng trầm của lịch sử dân tộc, với thiên nhiên đất nước, với tiếng nói của cha ông truyền từ đời này sang đời khác. Nhưng trong viễn tượng của một thế giới đang ngày càng thu hẹp lại, hay nói theo cách nói thời thượng, đang ngày càng “phẳng” đi, thì nguy cơ xói mòn phẩm chất dân tộc là một nguy cơ có thật.<br>Không thiếu những dẫn chứng trong văn học Việt Nam và thế giới cho thấy rằng một nhà văn yêu nước chưa hẳn là một nhà văn nhân đạo, nhưng một nhà văn nhân đạo bao giờ cũng là một nhà văn yêu nước, có tinh thần dân tộc sâu sắc. Đọc tác phẩm của những tác gia lớn thời Phục hưng như Dante, Petrarca, Boccaccio, ta thấy tràn đầy một tình yêu dành cho nước Ý, người Ý, tiếng Ý, đồng thời với tình cảm nhân văn cao quý. Ngòi bút của họ luôn thể hiện ước vọng Tổ quốc được thống nhất, dân tộc đoàn kết thành một khối vững chắc. Dante dù sống lưu vong nhưng luôn cất tiếng thơ ngợi ca Tổ quốc và kêu gọi dùng lưỡi gươm trừng phạt bọn hung tàn. Petrarca thì khơi gợi tinh thần công dân của người Ý trong việc vãn hồi hòa bình cho đất nước. Tinh thần yêu nước của họ gắn bó mật thiết với tiếng nói dân tộc, thúc đẩy họ sáng tác không chỉ bằng tiếng Latin mà còn bằng tiếng Ý thường ngày.<br>Đọc Chiến tranh và hòa bình của Tolstoi, ta xúc động trước vẻ đẹp tâm hồn thuần khiết của Natasha – một vẻ đẹp tưởng như mong manh nhưng lại góp phần tạo nên nội lực giúp nước Nga vượt qua sóng gió lịch sử. Phải có một tâm hồn Nga vĩ đại như Tolstoi mới cảm nhận thấu đáo sức mạnh ấy. Không phải ngẫu nhiên mà bài diễn văn nhận giải Nobel năm 1968 của Kawabata mang tên Sinh ra từ vẻ đẹp Nhật Bản, khẳng định chiều sâu nhân hậu, tinh tế của tâm hồn dân tộc.<br>Trong văn học Việt Nam, Nguyễn Trãi rất dân tộc trong Đại cáo bình Ngô, mà cũng rất dân tộc trong thơ ca thiên nhiên đất nước. Ở Nguyễn Du, phẩm chất dân tộc không chỉ thể hiện ở thái độ chính trị mà còn ở tâm hồn Việt bàng bạc trong từng câu thơ Truyện Kiều. Phong trào Thơ Mới (1932–1945) tuy tiếp thu yếu tố hiện đại phương Tây nhưng vẫn hòa quyện nhuần nhị với truyền thống dân tộc, tạo nên một diện mạo thơ ca vừa mới mẻ vừa đậm bản sắc.<br>Tuy nhiên, khi bàn về phẩm chất dân tộc, cần đề phòng thái độ dân tộc chủ nghĩa hẹp hòi. Dân tộc là một thực thể luôn vận động và phát triển, nên phẩm chất dân tộc cũng luôn thay đổi, bổ sung, không thể bị đóng khung. Không nên nhân danh giữ gìn bản sắc để ngăn cản cách tân. Lịch sử đã chứng minh điều đó: Pushkin từng bị phê phán là học đòi châu Âu, nhưng ngày nay lại được thừa nhận là tiếng nói rực rỡ của tâm hồn Nga. Điều đáng tiếc là bài học ấy không phải lúc nào người ta cũng ghi nhớ.<br>(Trích Nhập môn lí luận văn học, Huỳnh Như Phương)", "cauHoi": [{"question": "Quan điểm chính của văn bản là gì?", "choices": ["Phẩm chất dân tộc trong văn học chủ yếu được thể hiện qua tình yêu quê hương, tiếng nói dân tộc và việc bảo vệ truyền thống trước ảnh hưởng bên ngoài.", "Văn học lớn luôn gắn bó với dân tộc, nhưng phẩm chất dân tộc không nên bị hiểu như một khuôn mẫu đóng kín mà cần được nhìn nhận trong sự vận động, phát triển và giao lưu.", "Trong thời đại toàn cầu hóa, nguy cơ xói mòn phẩm chất dân tộc là vấn đề quan trọng nhất mà văn học cần giải quyết.", "Một nhà văn nhân đạo bao giờ cũng là nhà văn yêu nước, vì vậy phẩm chất dân tộc trước hết được xác lập từ tinh thần nhân đạo."], "correctIndex": 1, "explain": "<b>Câu 26. Chọn B. Giải thích: Tác giả khẳng định nhà văn lớn luôn gắn với dân tộc, nhưng đồng thời cảnh báo không nên hiểu bản sắc một cách cực đoan, đóng kín mà phải biết cách tân và phát triển.</b>"}, {"question": "Việc tác giả nhắc đến Dante, Petrarca, Boccaccio, Tolstoi, Kawabata, Nguyễn Trãi, Nguyễn Du và phong trào Thơ Mới chủ yếu nhằm mục đích gì?", "choices": ["Chứng minh rằng phẩm chất dân tộc của nhà văn thường được thể hiện trực tiếp nhất qua thái độ chính trị đối với đất nước.", "Khẳng định rằng nhà văn chỉ có thể giữ được bản sắc dân tộc khi hạn chế tiếp nhận các yếu tố văn học ngoại lai.", "So sánh văn học Việt Nam với văn học thế giới để cho thấy văn học Việt Nam có khả năng tiếp thu và vượt qua các trào lưu phương Tây.", "Làm rõ rằng phẩm chất dân tộc trong văn học có thể biểu hiện qua tình yêu đất nước, tiếng nói dân tộc, tâm hồn dân tộc và sự kết hợp sáng tạo giữa truyền thống với cách tân."], "correctIndex": 3, "explain": "<b>Câu 27. Chọn D. Giải thích: Các ví dụ này trải dài từ tình yêu đất nước (Dante), tâm hồn dân tộc (Kawabata, Tolstoi) đến sự kết hợp truyền thống - hiện đại (Thơ Mới), nhằm minh chứng cho sự đa dạng của phẩm chất dân tộc.</b>"}, {"question": "Nhận định nào sau đây không phù hợp với quan điểm của tác giả?", "choices": ["Phẩm chất dân tộc là một giá trị cố định, cần được bảo tồn nguyên vẹn bằng cách hạn chế ảnh hưởng từ bên ngoài.", "Phẩm chất dân tộc trong văn học có nguy cơ bị xói mòn trong bối cảnh toàn cầu hóa.", "Giữ gìn bản sắc dân tộc không đồng nghĩa với việc phủ nhận mọi nỗ lực cách tân và đổi mới văn học.", "Một tác phẩm văn học có thể tiếp thu yếu tố hiện đại phương Tây mà vẫn mang đậm bản sắc dân tộc."], "correctIndex": 0, "explain": "<b>Câu 28. Chọn A. Giải thích: Tác giả phản đối việc coi phẩm chất dân tộc là &quot;cố định&quot; hay &quot;đóng khung&quot; và khẳng định dân tộc luôn vận động.</b>"}, {"question": "Ý nghĩa lập luận của bằng chứng Pushkin trong đoạn cuối là gì?", "choices": ["Cho thấy phẩm chất dân tộc chỉ được thừa nhận sau khi nhà văn đã vượt qua sự đánh giá khắt khe của thời đại mình.", "Làm bằng chứng cho quan điểm không nên nhân danh bản sắc dân tộc để phủ nhận cách tân, vì đổi mới vẫn có thể làm giàu cho tinh thần dân tộc.", "Khẳng định văn học Nga đạt đến đỉnh cao khi thoát khỏi hoàn toàn ảnh hưởng của châu Âu.", "Chứng minh rằng mọi sự cách tân trong văn học ban đầu đều bị hiểu lầm và phê phán gay gắt."], "correctIndex": 1, "explain": "<b>Câu 29. Chọn B. Giải thích: Pushkin từng bị chê là &quot;học đòi châu Âu&quot; (cách tân) nhưng sau này lại là biểu tượng của tâm hồn Nga, cho thấy cách tân không làm mất đi bản sắc mà còn làm giàu thêm cho nó.</b>"}, {"question": "Đâu là phương án phản biện, mở rộng phù hợp nhất với quan điểm của văn bản?", "choices": ["Vì phẩm chất dân tộc luôn vận động, văn học không cần đặt ra vấn đề giữ gìn bản sắc trong bối cảnh toàn cầu hóa.", "Nếu nhà văn có tài năng sáng tạo, tác phẩm của họ tất yếu sẽ mang phẩm chất dân tộc mà không cần ý thức gìn giữ truyền thống.", "Dù không nên biến bản sắc dân tộc thành một khuôn mẫu đóng kín, việc tiếp thu và cách tân văn học vẫn cần có khả năng chọn lọc để tránh hòa tan vào những mô hình ngoại lai.", "Bản sắc dân tộc chủ yếu là vấn đề của lịch sử và ngôn ngữ, không liên quan trực tiếp đến cách tân nghệ thuật."], "correctIndex": 2, "explain": "<b>Câu 30. Chọn C. Giải thích: Đây là phương án mở rộng hợp lí nhất: ủng hộ việc giao lưu, cách tân nhưng nhấn mạnh cần có sự &quot;chọn lọc&quot; để không bị &quot;hòa tan&quot;, giữ vững bản sắc trong quá trình hội nhập.</b>"}], "khongXaoTron": true}], "anh": [{"noiDungChung": "<b><i>Câu 31-35: Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i></b>", "cauHoi": [{"question": "He’s always ready to take _____ new challenges in his career.", "choices": ["on", "over", "out", "in"], "correctIndex": 0, "explain": "<b>Câu 31. Chọn A</b><br><b>Giải thích: Cụm động từ &quot;take on&quot; có nghĩa là đảm nhận, gánh vác (công việc, thử thách).</b><br><b>Dịch: Anh ấy luôn sẵn sàng đảm nhận những thử thách mới trong sự nghiệp.</b>"}, {"question": "By the time we get to the airport, the flight _____ already.", "choices": ["will have departed", "will depart", "departs", "is departing"], "correctIndex": 0, "explain": "<b>Câu 32. Chọn A</b><br><b>Giải thích: Cấu trúc &quot;By the time + hiện tại đơn, tương lai hoàn thành will\\ have\\ Vp2 dùng để diễn tả một hành động sẽ hoàn thành trước một thời điểm hoặc một hành động khác trong tương lai.Dịch: Trước khi chúng ta đến sân bay, chuyến bay chắc đã khởi hành rồi.</b>"}, {"question": "He runs _____ than anyone else on the team.", "choices": ["more fast", "faster", "the fastest", "fastest ."], "correctIndex": 1, "explain": "<b>Câu 33. Chọn B</b><br><b>Giải thích: &quot;Fast&quot; là trạng từ ngắn. Cấu trúc so sánh hơn với trạng từ ngắn là </b><span class=\"ct\">adj/adv + -er + than</span><b>. (Không dùng &quot;more fast&quot;).</b>"}, {"question": "________ professionals work to prevent the spread of diseases and improve the<br>overall well-being of populations.", "choices": ["Publication health", "Publicity health", "Public health", "Publicized health"], "correctIndex": 2, "explain": "<b>Câu 34. Chọn C</b><br><b>Giải thích: Cụm danh từ cố định &quot;Public health&quot; có nghĩa là y tế công cộng.</b>"}, {"question": "His training regime is intense, but he always makes sure to take _____ rest to avoid<br>overtraining.", "choices": ["some", "a", "the", "any"], "correctIndex": 0, "explain": "<b>Câu 35. Chọn A</b><br><b>Giải thích: &quot;Rest&quot; (sự nghỉ ngơi) là danh từ không đếm được. Dùng &quot;some&quot; trong câu khẳng định để chỉ một lượng không xác định.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<i>Câu 36-40: Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.</i>", "cauHoi": [{"question": "He <u>is</u> always <u>asking</u> for <u>an</u> advice, but never <u>listens</u> to it.", "choices": ["is", "asking", "an", "listens"], "correctIndex": 2, "explain": "<b>Câu 36. Chọn C</b><br><b>Giải thích: &quot;Advice&quot; là danh từ không đếm được, nên không đi với mạo từ &quot;an&quot;.</b><br><b>Sửa lại: Bỏ &quot;an&quot; hoặc thay bằng &quot;some advice&quot; / &quot;a piece of advice&quot;.</b>"}, {"question": "<u>Neither</u> the teacher nor <u>the</u> students <u>was</u> ready for the <u>upcoming</u> exam.", "choices": ["neither", "the", "was", "upcoming."], "correctIndex": 2, "explain": "<b>Câu 37. Chọn C</b><br><b>Giải thích: Cấu trúc &quot;Neither A nor B&quot;, động từ chia theo chủ ngữ gần nhất (B). &quot;The students&quot; là số nhiều nên động từ phải là &quot;were&quot;. </b>"}, {"question": "Anna and Ben <u>are planning</u> a trip, but neither of <u>them</u> knows where <u>she</u> wants to go <u>yet</u>.", "choices": ["are planning", "them", "she", "yet"], "correctIndex": 2, "explain": "<b>Câu 38. Chọn C</b><br><b>Giải thích: &quot;Neither of them&quot; ở đây chỉ Anna và Ben (2 người). Đại từ thay thế phải dùng số nhiều &quot;they&quot; hoặc trung tính, nhưng vì nhắc đến cả 2 nên dùng &quot;they want&quot; là hợp lý nhất.</b><br><b>Sửa lại: they.</b>"}, {"question": "Their apartment, <u>where</u> is located near <u>the</u> city center, <u>is</u> both spacious and <u>affordable</u>", "choices": ["where", "near", "is", "affordable."], "correctIndex": 0, "explain": "<b>Câu 39. Chọn A</b><br><b>Giải thích: &quot;Where&quot; là trạng từ quan hệ thay thế cho nơi chốn nhưng không làm chủ ngữ cho động từ phía sau. Ở đây cần một đại từ quan hệ làm chủ ngữ cho &quot;is located&quot;.</b><br><b>Sửa lại: which.</b>"}, {"question": "The <u>workers</u> <u>tools</u> were left outside <u>as</u> <u>they</u> had no place to store them.", "choices": ["workers", "tools", "as", "upcoming"], "correctIndex": 0, "explain": "<b>Câu 40. Chọn A</b><br><b>Giải thích: Lỗi sở hữu cách. Phải là &quot;những dụng cụ của các công nhân&quot;.</b><br><b>Sửa lại: workers&#x27; (thêm dấu phẩy sau chữ s để chỉ sở hữu cách số nhiều).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<i>Câu 41-45: Which of the following best restates each of the given sentences?</i>", "cauHoi": [{"question": "&quot;Don’t touch the stove! It’s hot,&quot; she warned the child.", "choices": ["She warned the child that she doesn’t touch the stove as it’s hot.", "She warned the child not to touch the stove because it was hot.", "She warned the child not touching the stove as it’s hot.", "She warned the child to not touch the stove because it’s hot."], "correctIndex": 0, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án B, còn đáp án tô trong đề là A — web đang dùng A.)</i><br><b>Câu 41. Chọn B</b><br><b>Giải thích: Cấu trúc câu mệnh lệnh gián tiếp: warn\\ someone\\ not\\ to\\ V. Đồng thời lùi thì &quot;is&quot; thành &quot;was&quot;.</b>"}, {"question": "The bridge collapsed because of the heavy rain last night.", "choices": ["If it hadn&#x27;t rained heavily, the bridge would not have collapsed.", "The bridge collapsed because it was not strong enough.", "The heavy rain caused the bridge to collapse immediately.", "Unless the rain had been lighter, the bridge would have stayed intact."], "correctIndex": 0, "explain": "<b>Câu 42. Chọn A</b><br><b>Giải thích: Câu gốc ở quá khứ (last night), dùng câu điều kiện loại 3 (If S + had Vp2, S+ would have Vp2 để giả định ngược lại thực tế quá khứ.</b>"}, {"question": "Sarah&#x27;s handwriting is neat, but Emma’s handwriting is neater", "choices": ["Emma’s handwriting is not so neat as Sarah’s.", "Sarah’s handwriting is not so neat as Emma’s.", "Sarah’s handwriting is neater than Emma’s.", "Sarah’s handwriting is the neatest of all."], "correctIndex": 1, "explain": "<b>Câu 43. Chọn B</b><br><b>Giải thích: Sarah viết sạch, Emma viết sạch hơn </b><span class=\"ct\">→</span><b> Sarah viết không sạch bằng Emma (not so/as adj as).</b>"}, {"question": "Be careful when using the knife so that you don’t cut yourself.", "choices": ["Handle the knife carefully so as to cut yourself.", "Use the knife with care so you don’t get yourself injured.", "If you handle the knife properly, you would not be injured.", "The knife will not cause injury unless you handle it carefully."], "correctIndex": 1, "explain": "<b>Câu 44. Chọn B</b><br><b>Giải thích: Câu gốc khuyên cẩn thận để không bị đứt tay. Câu B đồng nghĩa: Sử dụng dao cẩn thận để không bị thương.</b>"}, {"question": "The university is losing applicants probably because of its high tuition fees.", "choices": ["High tuition fees might be the reason why the university is losing applicants.", "The university’s application rate is increasing despite its tuition fees.", "Tuition fees have not been raised, so it’s unlikely they are the cause.", "It is undeniable that high tuition fees are driving students away from the university."], "correctIndex": 0, "explain": "<b>Câu 45. Chọn A</b><br><b>Giải thích: &quot;Probably&quot; (có lẽ) tương ứng với &quot;might&quot; (có thể) trong câu restate để chỉ khả năng.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b><i>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question. Choose an option (A, B, C, or D) that best answers each question.</i></b><br><b>1.</b> Sleep deprivation is a condition that occurs when an individual gets less sleep than they need to<br>function properly. For adults, the recommended amount of sleep is between seven and nine hours per night, but many people fall short of <b><u>this</u></b> due to busy schedules, stress, or poor sleep habits. While missing a few hours of sleep occasionally might not seem like a big deal, <b><u>chronic</u></b> sleep deprivation can have serious consequences for both physical and mental health.<br><b>2.</b> One of the most immediate effects of sleep deprivation is reduced cognitive performance. When<br>you do not get enough sleep, it becomes harder to focus, solve problems, and make decisions. This can lead to mistakes at work or school, as well as an increased risk of accidents, especially while driving. Studies have shown that sleep-deprived drivers can be as impaired as those under the influence of alcohol.<br>3. In addition to cognitive issues, sleep deprivation also affects the body. It can weaken the immune system, making it harder to fight off illnesses. Long-term sleep deprivation is linked to more serious health problems such as heart disease, diabetes, and obesity. Lack of sleep can disrupt the hormones that regulate hunger, causing people to eat more and gain weight.<br>4. Sleep deprivation also has a significant impact on mental health. People who consistently get too little sleep are more likely to experience anxiety, depression, and mood swings. This can create a vicious cycle, as poor mental health can further disrupt sleep, making it even harder to recover.<br>5. Fortunately, there are steps that can help improve sleep habits. Setting a consistent bedtime, creating a relaxing nighttime routine, and limiting screen time before bed are all effective strategies. It’s also important to prioritize sleep and recognize that it’s as essential to health as diet and exercise. By taking these steps, individuals can reduce the risks associated with sleep deprivation and improve their overall quality of life.", "cauHoi": [{"question": "What is the passage mainly about?", "choices": ["The importance of diet and exercise for health", "How to recover from chronic sleep disorders", "The effects of sleep deprivation and how to address it", "Different sleep requirements for various age groups"], "correctIndex": 2, "explain": "<b>Câu 46. Chọn C</b><br><b>Giải thích: Bài viết nêu định nghĩa, tác hại (thể chất, tinh thần) và cách khắc phục tình trạng thiếu ngủ.</b>"}, {"question": "In paragraph 1, what does the word &quot;<b>this</b>&quot; refer to?", "choices": ["Sleep time", "Following a busy schedule", "Experiencing stress", "Developing good sleep habits"], "correctIndex": 0, "explain": "<b>Câu 47. Chọn A</b><br><b>Giải thích: &quot;This&quot; thay thế cho &quot;The recommended amount of sleep&quot; (khoảng thời gian ngủ được khuyến nghị).</b>"}, {"question": "In paragraph 1, what does the word &quot;<b>chronic</b>&quot; mean in the context of sleep<br>deprivation?", "choices": ["Occasional", "Long-term", "Sever", "Common."], "correctIndex": 1, "explain": "<b>Câu 48. Chọn B</b><br><b>Giải thích: &quot;Chronic&quot; trong y khoa/sức khỏe nghĩa là mãn tính, kéo dài (long-term).</b>"}, {"question": "In paragraph 3, which of the following is NOT mentioned as a health issue caused by sleep deprivation?", "choices": ["cardiovascular problems", "excessive weight gain", "eye-related disorders", "diabetes"], "correctIndex": 2, "explain": "<b>Câu 49. Chọn C</b><br><b>Giải thích: Đoạn 3 nhắc đến tim mạch (A), cân nặng (B), tiểu đường (D). Không nhắc đến các bệnh về mắt.</b>"}, {"question": "In paragraph 4, why is poor mental health considered a vicious cycle in relation to sleep deprivation?", "choices": ["It reduces physical performance and focus.", "It makes it more difficult to recover from a lack of sleep.", "It causes people to avoid seeking help.", "It directly leads to increased hunger and weight gain."], "correctIndex": 1, "explain": "<b>Câu 50. Chọn B</b><br><b>Giải thích: Đoạn 4 nói rằng sức khỏe tâm thần kém gây khó ngủ, và khó ngủ lại làm tâm thần tệ hơn </b><span class=\"ct\">→</span><b> khó phục hồi.</b>"}, {"question": "In paragraph 5, what can be inferred about improving sleep habits", "choices": ["It requires cutting down on social interactions.", "It is more effective than exercise for mental health.", "It should be priotized along with dietary and physical habits.", "It can completely eliminate stress and anxiety."], "correctIndex": 2, "explain": "<b>Câu 51. Chọn C</b><br><b>Giải thích: Đoạn cuối nhấn mạnh ngủ cũng quan trọng như chế độ ăn (diet) và tập thể dục (exercise).</b>"}, {"question": "According to paragraph 5, which of the following is an effective strategy for better sleep?", "choices": ["Exercising immediately before bed", "Reducing screen exposure before bed", "Sleeping whenever you feel tired", "Eating a heavy meal before bed."], "correctIndex": 1, "explain": "<b>Câu 52. Chọn B</b><br><b>Giải thích: Thông tin ở đoạn 5: &quot;limiting screen time before bed&quot;.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60: Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.</b><br>1. Spaced repetition is a highly effective learning method that has gained popularity among students, professionals, and lifelong learners. This technique is based on the concept of revisiting information at increasing intervals over time to improve memory retention. By spacing out review sessions, learners can consolidate their knowledge and reduce the likelihood of forgetting, which is a common issue when using traditional study methods.<br><b>2.</b> The science behind spaced repetition is rooted in how the brain processes and stores information.<br>When you first learn something new, your memory of it is the strongest immediately after learning but starts to fade over time. Spaced repetition counters <b><u>this natural forgetting curve</u></b> by presenting the material just before you’re likely to forget it. Each time you review, the interval before the next review increases, which helps to strengthen the neural connections associated with that knowledge.<br><b>3.</b> One of the key advantages of spaced repetition is its <b><u>efficiency</u></b>. Instead of spending hours repeatedly reviewing the same material, learners focus only on what they are close to forgetting. This makes the method particularly useful for mastering large amounts of information, such as<br>vocabulary in a new language, medical terminology, or historical dates. Tools like flashcards and digital applications, such as Anki or Quizlet, are often used to implement spaced repetition effectively.<br><b>4.</b> Another benefit of spaced repetition is that it promotes active recall, which is the process of actively retrieving information from memory rather than passively rereading or highlighting. Active recall has been shown to enhance long-term retention and deepen understanding of the<br>material.<br><b>5.</b> However, spaced repetition does require discipline and consistency. It may feel counterintuitive at first, as learners might want to focus on new material rather than revisiting older content. Additionally, setting up a spaced repetition schedule can take time and effort, especially without<br>the help of digital tools.<br><b>6.</b> Despite these challenges, spaced repetition has proven to be a game-changer in the world of education and self-improvement. By leveraging the brain’s natural ability to strengthen memories through repetition, this method helps learners achieve better results with less effort over time.", "cauHoi": [{"question": "The best title for the passage can be _____.", "choices": ["The Role of Active Recall in Learning", "Spaced Repetition: A Useful Learning Technique", "The Science of Memory Retention", "How Flashcards Revolutionize Education"], "correctIndex": 1, "explain": "<b>Câu 53. Chọn B</b><br><b>Giải thích: Bài viết giới thiệu tổng quan về kỹ thuật lặp lại ngắt quãng (Spaced Repetition).</b>"}, {"question": "The phrase &quot;this natural forgetting curve&quot; in paragraph 2 refers to _____.", "choices": ["the brain&#x27;s ability to remember information", "the fading of memory over time", "the process of strengthening neural connections", "the act of reviewing material frequently"], "correctIndex": 1, "explain": "<b>Câu 54. Chọn B</b><br><b>Giải thích: &quot;Forgetting curve&quot; (đường cong lãng quên) chỉ việc trí nhớ mờ nhạt dần theo thời gian.</b>"}, {"question": "In paragraph 3, spaced repetition is particularly useful for _____.", "choices": ["reducing study time for exams", "learning new skills in a short period", "memorizing large sets of information", "avoiding the need for digital tools"], "correctIndex": 2, "explain": "<b>Câu 55. Chọn C</b><br><b>Giải thích: Đoạn 3: &quot;...useful for mastering large amounts of information&quot;.</b>"}, {"question": "In paragraph 3, the word &quot;efficiency&quot; can be replaced by _____.", "choices": ["flexibility", "effectiveness", "productivity", "simplicity"], "correctIndex": 1, "explain": "<b>Câu 56. Chọn B</b><br><b>Giải thích: Efficiency (sự hiệu quả/năng suất) tương đồng với Effectiveness (sự hiệu quả).</b>"}, {"question": "According to paragraph 4, active recall involves _____.", "choices": ["reading information multiple times", "retrieving information from memory", "highlighting key points for review", "passively observing study material."], "correctIndex": 1, "explain": "<b>Câu 57. Chọn B</b><br><b>Giải thích: Đoạn 4 định nghĩa: &quot;...actively retrieving information from memory&quot;.</b>"}, {"question": "In paragraph 5, which of the following is <b>NOT</b> mentioned as a challenge of spaced<br>repetition?", "choices": ["The initial effort needed to create a schedule", "The discipline required for consistent review", "The lack of effective tools for implementation", "The temptation to prioritize new material"], "correctIndex": 2, "explain": "<b>Câu 58. Chọn C</b><br><b>Giải thích: Đoạn 5 nhắc đến kỷ luật (B), sự cám dỗ học cái mới (D), tốn thời gian lên lịch (A). Không nói là &quot;thiếu công cụ&quot; (thực tế bài nói có công cụ như Anki, Quizlet).</b>"}, {"question": "It can be inferred from paragraph 5 that spaced repetition _____.", "choices": ["is only effective with digital tools", "may seem against common sense of learners at first", "requires less effort than other study methods", "completely eliminates the forgetting curve"], "correctIndex": 1, "explain": "<b>Câu 59. Chọn B</b><br><b>Giải thích: Đoạn 5: &quot;It may feel counterintuitive at first&quot; (Ban đầu có vẻ ngược đời/trái với trực giác).</b>"}, {"question": "The overall purpose of the passage is to _____.", "choices": ["highlight the limitations of traditional study methods", "explain the science behind memory and learning", "introduce the benefits and challenges of spaced repetition", "compare different tools used for education"], "correctIndex": 2, "explain": "<b>Câu 60. Chọn C</b><br><b>Giải thích: Mục đích chính là giới thiệu cả mặt lợi ích (benefits) và khó khăn (challenges) của phương pháp này.</b>"}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Trong hóa học phân tích, phương pháp nung nóng một mẫu chất và theo dõi sự thay đổi khối lượng của nó theo nhiệt độ được gọi là phân tích nhiệt trọng trường (TGA). Kết quả thường được biểu diễn qua một đồ thị cho thấy khối lượng mất đi (dưới dạng %) tương ứng với các giai đoạn biến đổi hóa học.<br>Hình bên mô tả quá trình nung nóng đồng(II) sunfat ngậm nước (<span class=\"ct\">CuSO<sub>4</sub>.5H<sub>2</sub>O</span>), còn gọi là đá xanh. Khi nhiệt độ tăng, các phân tử nước liên kết trong tinh thể sẽ dần tách ra và bay hơi, làm khối lượng chất rắn còn lại giảm xuống theo từng “bậc thang”.<br>Vùng chuyển đổi (đoạn dốc): Phản ánh quá trình giải phóng hơi nước mạnh mẽ khi nhiệt độ vượt ngưỡng năng lượng để phá vỡ các liên kết trong tinh thể.<br>Vùng ổn định nhiệt (đoạn ngang): Đánh dấu trạng thái cấu hình hóa học mới bền vững. Khối lượng không đổi do các phân tử nước còn lại có lực liên kết khác biệt, cần mức nhiệt cao hơn mới có thể tiếp tục tách ra.<br><b>Câu 103.</b> Dựa vào đồ thị, xét các mệnh đề sau:<br>1. Quá trình mất nước của <span class=\"ct\">CuSO<sub>4</sub>.5H<sub>2</sub>O</span> diễn ra liên tục và không có giai đoạn tạm dừng.<br>2. Tại khoảng nhiệt độ từ <span class=\"ct\">200°C</span> đến <span class=\"ct\">250°C</span>, khối lượng chất rắn hầu như không thay đổi.<br>3. Tổng độ giảm khối lượng sau khi kết thúc giai đoạn nung ở <span class=\"ct\">400°C</span> là <span class=\"ct\">36,14%</span>.", "cauHoi": [{"question": "Để thu được <span class=\"ct\">CuSO<sub>4</sub></span> khan hoàn toàn (mất toàn bộ 5 phân tử nước), chỉ cần nung mẫu đến <span class=\"ct\">150°C</span>.<br><b>Hỏi có bao nhiêu mệnh đề không phù hợp với dữ liệu đồ thị?</b>", "choices": ["1", "2", "3", "4"], "correctIndex": 1, "explain": "<b>HD:</b><br>1. <b>Ý 1 (Sai):</b> Đồ thị có các đoạn nằm ngang rõ rệt, không phải diễn ra liên tục.<br>2. <b>Ý 2 (Đúng):</b> Như đã phân tích ở trên, khối lượng không đổi trong khoảng <span class=\"ct\">200°C − 250°C</span>.<br>3. <b>Ý 3 (Đúng):</b> Tổng độ giảm là <span class=\"ct\">28,89% + 7,25% = 36,14%</span>. Tại <span class=\"ct\">400°C</span>, đồ thị đã đi ngang ở mức này.<br>4. <b>Ý 4 (Sai):</b> Tại <span class=\"ct\">150°C</span>, khối lượng vẫn đang trong đà giảm mạnh, chưa đạt đến trạng thái khan hoàn toàn (đoạn nằm ngang cuối cùng).<br><b>Hỏi số mệnh đề KHÔNG PHÙ HỢP:</b> Có 2 ý sai (ý 1 và ý 4). =&gt; <b>Đáp án chọn: B.</b>"}, {"question": "Dựa vào bối cảnh bài đọc về &quot;Vùng ổn định nhiệt&quot; (đoạn ngang) và &quot;Vùng chuyển đổi&quot; (đoạn dốc), hãy xác định nhận định nào sau đây mô tả đúng nhất về mối quan hệ giữa nhiệt độ và cấu trúc của mẫu <span class=\"ct\">CuSO<sub>4</sub>.5H<sub>2</sub>O</span> trong thí nghiệm?", "choices": ["Khi nhiệt độ nằm trong vùng ổn định nhiệt, năng lượng cung cấp chưa đủ để phá vỡ các liên kết hóa học của nhóm phân tử nước tiếp theo.", "Càng lên cao, các đoạn nằm ngang càng dài ra chứng tỏ các phân tử nước cuối cùng dễ bị tách rời hơn các phân tử nước đầu tiên.", "Trong các vùng chuyển đổi, khối lượng mẫu giảm đi là do sự thăng hoa của các ion đồng (<span class=\"ct\">Cu<sup>2+</sup></span>) và sunfat (<span class=\"ct\">SO<sub>4</sub><sup>2−</sup></span>).", "Đồ thị cho thấy chỉ cần duy trì nhiệt độ ở mốc <span class=\"ct\">100°C</span> trong thời gian đủ dài, mẫu chất sẽ mất hoàn toàn 5 phân tử nước mà không cần tăng nhiệt độ thêm."], "correctIndex": 0, "explain": "<b>HD:</b><br><b>Đáp án đúng: A</b><br>Giải thích: Nhận định A (Đúng): Vùng ổn định nhiệt (đoạn ngang) xuất hiện vì nhiệt độ hiện tại chưa đạt đến ngưỡng năng lượng cần thiết để phá vỡ các liên kết hóa học của nhóm phân tử nước tiếp theo.<br>Nhận định B (Sai): Các đoạn nằm ngang xuất hiện chứng tỏ các phân tử nước sau khó tách rời hơn vì cần mức nhiệt cao hơn để tiếp tục quá trình tách nước.<br>Nhận định C (Sai): Khối lượng giảm ở các vùng chuyển đổi là do sự giải phóng hơi nước, không phải do sự thăng hoa của các ion đồng hay sunfat.<br>Nhận định D (Sai): Do các phân tử nước có lực liên kết không đồng nhất, quá trình tách nước chỉ tiếp diễn khi nhiệt độ được nâng lên mức cao hơn chứ không phụ thuộc vào việc duy trì thời gian ở mức nhiệt thấp."}, {"question": "Thành phần gần nhất của chất rắn sau khi nhiệt độ đạt đến <span class=\"ct\">200°C</span> là(Cho biết nguyên tử khối của các nguyên tố: <span class=\"ct\">H = 1;O = 16;S = 32;Cu = 64</span>.)", "choices": ["<span class=\"ct\">CuSO<sub>4</sub>·H<sub>2</sub>O</span>.", "<span class=\"ct\">CuSO<sub>4</sub>·4H<sub>2</sub>O</span>.", "<span class=\"ct\">CuSO<sub>4</sub></span>.", "CuO ."], "correctIndex": 0, "explain": "<b>HD:</b> <span class=\"ct\">CuSO<sub>4</sub>.5H<sub>2</sub>O</span><br>Quan sát đồ thị, tại nhiệt độ <span class=\"ct\">200°C</span>, độ giảm khối lượng của mẫu đạt mức <span class=\"ct\">28,89%</span>.<br>Khối lượng giảm đi (tương ứng với lượng nước bay hơi):<br><span class=\"ct\">ΔM = 250 × 28,89% ≈ 72,225 g/mol</span><br>Số mol nước đã mất đi:<img class=\"anh-de\" src=\"data/anh/l14/caef89d2fa77b283.png\" alt=\"\" style=\"width:184px;height:42px;vertical-align:middle\"><br>Lượng nước còn lại trong tinh thể sau khi nung đến <span class=\"ct\">200°C</span> là:<span class=\"ct\">5 − 4 = 1 mol H<sub>2</sub>O</span><br>Vậy thành phần của chất rắn lúc này tương ứng với công thức: <span class=\"ct\">CuSO<sub>4</sub>.H<sub>2</sub>O</span>."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Kỹ thuật khối phổ (Mass Spectrometry) là phương pháp dùng để xác định chính xác khối lượng của các hạt ở cấp độ vi mô. Trong vùng điện từ trường mạnh, các mẫu chất (như khí Chlorine <span class=\"ct\">Cl<sub>2</sub></span>) được bắn phá bằng dòng electron năng lượng cao để chuyển thành các ion dương (<span class=\"ct\">[Cl]<sup>+</sup>,[Cl<sub>2</sub>]<sup>+</sup></span>), tạo ra các mảnh ion có khối lượng khác nhau. Sau đó, các ion sau khi tạo thành sẽ được đẩy qua một hiệu điện thế U (rất lớn) để gia tốc đến cùng một vận tốc. Động năng thu được là: \\(\\frac{1}{2}mv^2 = qU\\). Dòng ion bay vào một vùng có từ trường đều \\(\\vec{B}\\) đặt vuông góc với hướng chuyển động. Tại đây, lực Lorentz tác dụng lên các hạt mang điện, đóng vai trò là lực hướng tâm làm chúng chuyển động tròn với bán kính <span class=\"ct\">R</span> xác định bởi công thức: \\(R = \\frac{m \\cdot v}{q \\cdot B}\\). Dựa trên nguyên lý này, các ion có tỉ số khối lượng trên điện tích (<span class=\"ct\">m/q</span>) khác nhau sẽ có quỹ đạo khác nhau và đập vào đầu dò tại các vị trí riêng biệt. Kết quả được hiển thị qua đồ thị phổ khối, nơi mỗi đỉnh (peak) đại diện cho một loại hạt với độ cao tương ứng với tỉ lệ phần trăm (độ phổ biến) của nó trong mẫu chất.", "cauHoi": [{"question": "Dựa vào hình ảnh, các ion <span class=\"ct\">[Cl]<sup>+</sup></span> tại vị trí <span class=\"ct\">m/z = 35</span> và các ion phân tử <span class=\"ct\">[Cl<sub>2</sub>]<sup>+</sup></span> tại vị trí <span class=\"ct\">m/z = 70</span> cùng được gia tốc đến một vận tốc <span class=\"ct\">v</span> và bay vào cùng một từ trường đều <span class=\"ct\">B</span>. Bán kính quỹ đạo của ion nào sẽ lớn hơn và lớn hơn bao nhiêu lần?", "choices": ["Ion <span class=\"ct\">[Cl<sub>2</sub>]<sup>+</sup></span> có bán kính lớn hơn và gấp 2 lần ion <span class=\"ct\">[Cl]<sup>+</sup></span>.", "Ion <span class=\"ct\">[Cl]<sup>+</sup></span> có bán kính lớn hơn và gấp 2 lần ion <span class=\"ct\">[Cl<sub>2</sub>]<sup>+</sup></span>.", "Hai ion có bán kính bằng nhau vì tỉ số <span class=\"ct\">m/z</span> của chúng tỉ lệ thuận với nhau.", "Ion <span class=\"ct\">[Cl<sub>2</sub>]<sup>+</sup></span> có bán kính lớn hơn và gấp \\(\\sqrt{2}\\) lần ion <span class=\"ct\">[Cl]<sup>+</sup></span>."], "correctIndex": 0, "explain": "<b>Đáp án: A. </b>(Giải thích: Theo công thức \\(R = \\frac{m \\cdot v}{q \\cdot B}\\). Với cùng v, q, B, bán kính <span class=\"ct\">R</span> tỉ lệ thuận với khối lượng <span class=\"ct\">m</span>. Vì <span class=\"ct\">m</span> của <span class=\"ct\">[Cl<sub>2</sub>]<sup>+</sup></span> là 70, gấp đôi <span class=\"ct\">m</span> của <span class=\"ct\">[Cl]<sup>+</sup></span> là 35, nên bán kính quỹ đạo của nó sẽ gấp 2 lần)."}, {"question": "Để tách hai ion có khối lượng rất gần nhau như <span class=\"ct\">[<sup>35</sup>Cl]<sup>+</sup></span> (<span class=\"ct\">m = 35</span>) và <span class=\"ct\">[<sup>35</sup>Cl − <sup>37</sup>Cl]<sup>+</sup></span> (<span class=\"ct\">m = 72</span>), máy khối phổ cần một độ phân giải cao. Nếu muốn khoảng cách giữa hai vị trí đập của ion trên đầu dò (tương ứng với 2R) lớn hơn, kỹ thuật viên nên điều chỉnh máy như thế nào?", "choices": ["Tăng cường độ từ trường B.", "Giảm cường độ điện trường E.", "Tăng hiệu điện thế gia tốc U.", "Tăng điện tích của các ion bằng cách ion hóa nhiều lần."], "correctIndex": 2, "explain": "<b>Đáp án: C.</b> (Giải thích: Để khoảng cách giữa các ion lớn hơn, ta cần bán kính <span class=\"ct\">R</span> lớn hơn. Từ công thức \\(R = \\sqrt{\\frac{2mU}{qB^2}}\\), ta thấy <span class=\"ct\">R</span> tỉ lệ thuận với \\(\\sqrt{U}\\). Do đó, tăng <span class=\"ct\">U</span> sẽ làm tăng <span class=\"ct\">R</span> và kéo dãn khoảng cách giữa các vạch phổ trên đầu dò)."}, {"question": "Nếu ta thay thế mẫu khí Chlorine (<span class=\"ct\">Cl<sub>2</sub></span>) bằng mẫu khí Fluorine (nguyên tố <span class=\"ct\">F</span> chỉ có duy nhất một đồng vị là <span class=\"ct\"><sup>19</sup>F</span>), thì vùng phổ phân tử của khí Fluorine (<span class=\"ct\">F<sub>2</sub></span>) trên đồ thị sẽ thay đổi như thế nào so với đồ thị?", "choices": ["Sẽ có 3 vạch tương tự như Chlorine nhưng ở vị trí số khối nhỏ hơn.", "Sẽ chỉ có duy nhất 1 vạch tại vị trí <span class=\"ct\">m/z = 38</span>.", "Sẽ có rất nhiều vạch vì Fluorine hoạt động hóa học mạnh hơn Chlorine.", "Sẽ không xuất hiện vạch nào vì Fluorine không bị ion hóa."], "correctIndex": 1, "explain": "<b>Đáp án: B.</b> (Giải thích: Vì Fluorine chỉ có một loại đồng vị <span class=\"ct\"><sup>19</sup>F</span>, nên mọi phân tử <span class=\"ct\">F<sub>2</sub></span> đều có khối lượng giống hệt nhau là <span class=\"ct\">19 + 19 = 38</span>. Do đó máy chỉ ghi nhận được đúng một đỉnh phổ duy nhất tại vị trí này)."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br><img class=\"anh-de\" src=\"data/anh/l14/7695fda7657faca0.png\" alt=\"\" style=\"width:275px;height:409px\">Hệ tuần hoàn hoạt động nhờ lực co bóp của tim đẩy máu vào hệ mạch, tạo nên huyết áp. Do tim hoạt động theo chu kỳ co - giãn nên huyết áp biến động giữa hai mức: huyết áp tâm thu (lúc tim co, đạt khoảng 110 – 120 mmHg) và huyết áp tâm trương (lúc tim giãn, đạt khoảng 70 – 80 mmHg). Theo biểu đồ, huyết áp giảm dần từ động mạch đến mao mạch và thấp nhất ở tĩnh mạch. Về mặt động lực học, vận tốc máu có mối quan hệ với tổng tiết diện mạch qua biểu thức: \\(v = \\frac{Q}{S}\\).<i> Trong đó: </i><span class=\"ct\">Q</span><i> là lưu lượng máu (lượng máu tim bơm đi trong 1 đơn vị thời gian), </i><span class=\"ct\">S</span><i> là tổng diện tích mặt cắt ngang của các mạch máu.</i><br>Tại hệ thống mao mạch, dù từng mạch rất nhỏ nhưng <b>tổng tiết diện</b> của chúng lại đạt giá trị cực đại, khiến vận tốc máu tại đây giảm xuống mức thấp nhất để tối ưu hóa việc trao đổi chất. Ngược lại, ở động mạch chủ có tổng tiết diện nhỏ nhất thì vận tốc máu chảy là nhanh nhất.<br><b> Câu 109:</b> Dựa vào hình ảnh và nội dung bài đọc, hãy cho biết có bao nhiêu mệnh đề sau đây là <b>đúng</b> khi nói về các chỉ số huyết động học trong hệ mạch:<br>1. Huyết áp giảm dần trong hệ mạch và đạt giá trị thấp nhất ở tĩnh mạch chủ.<br>2. Vận tốc máu tỉ lệ thuận với tổng tiết diện mạch; máu chảy nhanh nhất ở nơi có tổng tiết diện lớn nhất.<br>3. Tại hệ thống mao mạch, vận tốc máu giảm xuống mức thấp nhất để hỗ trợ quá trình trao đổi chất.", "cauHoi": [{"question": "Huyết áp tâm trương là chỉ số huyết áp đo được khi tim đang ở trạng thái co bóp để đẩy máu.", "choices": ["1.", "2.", "3.", "4."], "correctIndex": 1, "explain": "<b>Chọn B (Có 2 mệnh đề đúng là 1 và 3).</b><br><b>Mệnh đề 1 ĐÚNG:</b> Biểu đồ huyết áp cho thấy trị số giảm liên tục từ động mạch chủ đến tĩnh mạch chủ.<br><b>Mệnh đề 2 SAI:</b> Vận tốc máu tỉ lệ <b>nghịch</b> với tổng tiết diện. Nơi có tổng tiết diện lớn nhất (mao mạch) thì vận tốc máu phải chậm nhất.<br><b>Mệnh đề 3 ĐÚNG:</b> Tại mao mạch, tổng tiết diện cực đại nên vận tốc cực tiểu, giúp tối ưu hóa việc trao đổi chất.<br><b>Mệnh đề 4 SAI:</b> Huyết áp tâm trương ứng với lúc tim đang <b>giãn</b> (nghỉ), còn huyết áp khi tim co là huyết áp tâm thu."}, {"question": "Dựa vào thông tin về cơ chế co bóp của tim, huyết áp tâm thu và huyết áp tâm trương xuất hiện tương ứng với trạng thái nào của tim?", "choices": ["Tim co – Tim giãn.", "Tim giãn – Tim co.", "Máu chảy đi – Máu đứng yên.", "Động mạch co – Động mạch giãn."], "correctIndex": 0, "explain": "<b>Câu 110: Chọn A.</b> Giải thích: Bài đọc nêu &quot;Huyết áp tâm thu là áp lực cao nhất khi tim co&quot;."}, {"question": "Giả sử tại một tiểu động mạch, tổng diện tích mặt cắt ngang (<img class=\"anh-de\" src=\"data/anh/l14/765754161b3120bc.png\" alt=\"\" style=\"width:15px;height:18px;vertical-align:middle\">) là <img class=\"anh-de\" src=\"data/anh/l14/7d70503816077306.png\" alt=\"\" style=\"width:48px;height:22px;vertical-align:middle\"> và vận tốc máu (<img class=\"anh-de\" src=\"data/anh/l14/a805d505374409c2.png\" alt=\"\" style=\"width:13px;height:15px;vertical-align:middle\">) đo được là <img class=\"anh-de\" src=\"data/anh/l14/e7e63dcdce06a43f.png\" alt=\"\" style=\"width:55px;height:18px;vertical-align:middle\">. Khi máu đi vào hệ thống mao mạch tiếp theo, do số lượng mao mạch rất lớn nên tổng tiết diện (<img class=\"anh-de\" src=\"data/anh/l14/b1d06437f2a9edd7.png\" alt=\"\" style=\"width:15px;height:18px;vertical-align:middle\">) tăng gấp 20 lần. Hãy tính vận tốc máu tại hệ thống mao mạch này?", "choices": ["<img class=\"anh-de\" src=\"data/anh/l14/8c9e5e172343e679.png\" alt=\"\" style=\"width:65px;height:18px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l14/be0b7ab254b99a81.png\" alt=\"\" style=\"width:54px;height:20px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l14/ada8ed4368f237ec.png\" alt=\"\" style=\"width:45px;height:18px;vertical-align:middle\">", "<img class=\"anh-de\" src=\"data/anh/l14/d4ed0e92788a4ed9.png\" alt=\"\" style=\"width:54px;height:18px;vertical-align:middle\">"], "correctIndex": 2, "explain": "<b>Câu 3: Chọn C.</b><br><i>Hướng dẫn:</i> Vì vận tốc tỉ lệ nghịch với tổng tiết diện (<img class=\"anh-de\" src=\"data/anh/l14/604f509207909441.png\" alt=\"\" style=\"width:88px;height:24px;vertical-align:middle\">).<br>Nếu tiết diện <img class=\"anh-de\" src=\"data/anh/l14/5629ae9ac73de47e.png\" alt=\"\" style=\"width:15px;height:18px;vertical-align:middle\"> tăng gấp 20 lần thì vận tốc <img class=\"anh-de\" src=\"data/anh/l14/a805d505374409c2.png\" alt=\"\" style=\"width:13px;height:15px;vertical-align:middle\"> phải giảm đi 20 lần.<br>Vận tốc tại mao mạch = <img class=\"anh-de\" src=\"data/anh/l14/50bb27ee1d16272a.png\" alt=\"\" style=\"width:103px;height:18px;vertical-align:middle\">."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>Trong 5 năm qua, các địa phương ở khu vực Bắc Trung Bộ đã chủ động, tích cực phát triển khai thực hiện các chủ trương, đường lối của Đảng về quản lý, bảo vệ và phát triển rừng, nhất là Chỉ thị số 13 - CT/TW và đã đạt được nhiều kết quả quan trọng, tạo ra sự chuyển biến mạnh mẽ về nhận thức, nâng cao ý thức trách nhiệm của cả hệ thống chính trị và toàn xã hội. Ngành lâm nghiệp đã từng bước phát triển khá nhanh, từng bước khẳng định được định vị thế, khép lại cuộc chơi phát triển kinh tế - xã hội của khu vực, góp phần nâng cao đời sống nhân dân. Diện tích rừng trồng tăng trưởng nhanh; diện rừng tự nhiên, hệ sinh thái rừng và đa dạng sinh học được bảo vệ khá tốt, mức độ phủ rừng cao nhất so với các vùng trên cả nước ( <span class=\"ct\">57,4%</span> ), tăng <span class=\"ct\">0,9%</span> so với trước khi có chỉ thị 13 . Công nghiệp chế biến gỗ và lâm sản ngoài gỗ phát triển khá. Các cơ chế, chính sách về phát triển lâm nghiệp từng bước được quan tâm và hoàn thiện. Đặc biệt, Bắc Trung Bộ là vùng đầu tiên của cả nước được Chính phủ cho phát triển thí nghiệm điểm chuyển tín hiệu carbon duy nhất theo Nghị định 107/2022/NĐ-CP ngày 28/12/2022.<br>(Nguồn: ttdn.vn, 2023)", "cauHoi": [{"question": "Bắc Trung Bộ là vùng có", "choices": ["mức độ che phủ rừng thấp nhất cả nước", "mức độ che phủ rừng cao nhất so với các vùng trên cả nước ( 57,4 % )", "diện tích rừng lớn nhất cả nước", "diện tích rừng ngày càng giảm"], "correctIndex": 1, "explain": "<b>Đáp án: B</b><br>Giải thích: Dựa vào đoạn trích trên &quot;Diện tích rừng trồng tăng trưởng nhanh; diện rừng tự nhiên, hệ sinh thái riêng và đa dạng sinh học được bảo vệ khá tốt, mức độ phủ rừng cao nhất so với các vùng trên cả nước <span class=\"ct\">(57,4%)</span>, tăng 0,9 % so với trước khi có chỉ thị 13 ."}, {"question": "Tỉ lệ che phủ rừng được hiểu", "choices": ["là tỷ lệ phần trăm giữa diện tích rừng hiện có so với tổng diện tích đất tự nhiên trên một phạm vi địa lý nhất định.", "là tỷ lệ phần trăm giữa diện tích rừng hiện có so với tổng diện tích rừng tự nhiên.", "là tỷ lệ phần trăm giữa rừng trồng hiện có so với tổng diện tích rừng tự nhiên.", "là tỷ lệ phần trăm giữa diện tích rừng tự nhiên và rừng trồng hiện có so với tổng diện tích rừng."], "correctIndex": 0, "explain": "<b>Đáp án: A.</b><br>Giải thích: Công thức tính tỷ lệ che phủ rừng:<br>Tỷ lệ che phủ rừng % = (Diện tích rừng hiện có/Tổng diện tích đất tự nhiên) <span class=\"ct\">× 100</span>"}, {"question": "Phát biểu nào sau đây đúng về tài nguyên rừng của nước ta hiện nay?", "choices": ["Chất lượng rừng đã được phục hồi hoàn toàn.", "Rừng nghèo và mới phục hồi chiếm tỉ lệ lớn.", "Diện tích rừng giảm nhanh, liên tục.", "Diện tích rừng giàu chiếm tỉ lệ lớn."], "correctIndex": 1, "explain": "<b>Đáp án: B</b><br><b>Giải thích </b>A sai vì chất lượng riêng chưa được phục hồi.<br>C sai vì diện tích rừng liên tục tăng.<br>D sai vì nước ta diện tích rừng giàu chiếm tỉ lệ nhỏ, chủ yếu là rừng nghèo và rừng mới phục hồi."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117 </b><br>Với cương vị là phái viên của Quốc tế Cộng sản, có quyền quyết định mọi vấn đề liên quan tới phong trào cách mạng ở Đông Dương, Nguyễn Ái Quốc chủ động triệu tập đại biểu của Đông Dương Cộng sản đảng và An Nam Cộng sản đảng đến Cửu Long (Hương Cảng, Trung Quốc) để bàn việc hợp nhất.<br>Hội nghị hợp nhất các tổ chức cộng sản bắt đầu họp từ ngày 6-1-1930 tại Cửu Long, do Nguyễn Ái Quốc chủ trì. Dự Hội nghị có Trịnh Đình Cửu và Nguyễn Đức Cảnh là đại biểu của Đông Dương Cộng sản đảng, Châu Văn Liêm và Nguyễn Thiệu là đại biểu của An Nam Cộng sản đảng.<br>Nguyễn Ái Quốc phê phán những quan điểm sai lầm của các tổ chức công sản riêng rẽ và nếu chương trình Hội nghị.<br>Hội nghị đã thảo luận và nhất trí thống nhất các tổ chức cộng sản thành một đảng duy nhất lấy tên là <i>Đảng Cộng sản Việt Nam</i>, thông qua <i>Chính cường vắn tắt của Đảng, Sách lược vắn tắt của Đảng</i>,... do Nguyễn Ái Quốc soạn thảo. Đó là <i>Cương lĩnh chính trị đầu tiên </i>của Đảng Cộng sản Việt Nam.<br>Cương lĩnh xác định đường lối chiến lược cách mạng của Đảng là tiến hành “tư sản dân quyền cách mạng và thổ địa cách mạng để đi tới xã hội cộng sản”. Nhiệm vụ của cuộc cách mạng là đánh đổ đế quốc Pháp, bọn phong kiến và tư sản phản cách mạng, làm cho nước Việt Nam được độc lập tự do; lập chính phủ công nông binh, tổ chức quân đội công nông; tịch thu hết sản nghiệp lớn của đế quốc; tịch thu ruộng đất của đế quốc và bọn phản cách mạng chia cho dân cày nghèo, tiến hành cách mạng ruộng đất v.v... Lực lượng cách mạng là công nhân, nông dân, tiểu tư sản, trí thức ; còn phú nông, trung, tiểu địa chủ và tư sản thì lợi dụng hoặc trung lập, đồng thời phải liên lạc với các dân tộc bị áp bức và vô sản thế giới. Đảng Cộng sản Việt Nam – đội tiên phong của giai cấp vô sản – sẽ giữ vai trò lãnh đạo cách mạng. Cương lĩnh chính trị đầu tiên của Đảng Cộng sản Việt Nam do Nguyễn Ái Quốc soạn thảo là một cương lĩnh cách mạng giải phóng dân tộc sáng tạo, kết hợp đúng đến vấn đề dân tộc và vấn đề giai cấp. Độc lập và tự do là tư tưởng cốt lõi của cương lĩnh này.<br>(Nguồn: SGK Lịch sử 12)", "cauHoi": [{"question": "Tư tưởng cốt lõi của Cương lĩnh chính trị đầu tiên do Nguyễn Ái Quốc soạn thảo là", "choices": ["độc lập và tự do.", "độc lập và thống nhất.", "tự do và bình đẳng.", "hòa bình và độc lập."], "correctIndex": 0, "explain": "<b>Chọn A.</b><br><b>Phương pháp: </b>Dựa vào thông tin được cung cấp để trả lời<br><b>Cách giải:</b><br>Tư tưởng cốt lõi của cương lĩnh chính trị đầu tiên do Nguyễn Ái Quốc soạn thảo là độc lập và tự do."}, {"question": "Dự Hội nghị hợp nhất các tổ chức cộng sản có các đại biểu đại diện cho các tổ chức", "choices": ["Đông Dương Cộng sản đảng và Đông Dương Cộng sản liên đoàn.", "Đông Dương Cộng sản liên đoàn và An Nam Cộng sản đảng.", "Đông Dương Cộng sản đảng và An Nam Cộng sản đảng.", "Đông Dương Cộng sản đảng, An Nam Cộng sản đảng và Đông Dương Cộng sản liên đoàn."], "correctIndex": 2, "explain": "<b>Chọn C.</b><br><b>Cách giải: </b>Hội nghị hợp nhất các tổ chức cộng sản bắt đầu họp từ ngày 6-1-1930 tại Cửu Long, do Nguyễn Ái Quốc chủ trì. Dự Hội nghị có Trịnh Đình Cửu và Nguyễn Đức Cảnh là đại biểu của Đông Dương Cộng sản đảng, Châu Văn Liêm và Nguyễn Thiệu là đại biểu của An Nam Cộng sản đảng."}, {"question": "So với điều kiện ra đời của các Đảng Cộng sản ở các nước tư bản, sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930 có thêm nhân tố nào sau đây?", "choices": ["Chủ nghĩa Mác – Lê-nin.", "Phong trào công nhân.", "Phong trào nông dân.", "Phong trào yêu nước."], "correctIndex": 3, "explain": "<b>Chọn D</b><br><b>Phương pháp: </b>so sánh<br><b>Cách giải:</b><br>Điều kiện ra đời của Đảng Cộng sản: Chủ nghĩa Mác – Lê-nin + phong trào công nhân.<br>Đảng Cộng sản Việt Nam ra đời dựa trên sự kết hợp: Chủ nghĩa Mác – Lê-nin + phong trào công nhân + phong trào yêu nước. =&gt; So với điều kiện ra đời của các Đảng cộng sản ở các nước tư bản, sự ra đời của Đảng Cộng sản Việt Nam đầu năm 1930 có thêm nhân tố là phong trào yêu nước."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Với mong muốn xây dựng thành công chuỗi cửa hành phân phối thực phẩm sạch trên địa bàn huyện X. Sau khi tham khảo một số mô hình cũng như kiến thức cơ bản về lĩnh vực kinh doanh này. Anh H đã lên kế hoạch chi tiết để thực hiện ý tưởng kinh doanh của mình. Qua tìm hiểu thực tế anh nhận thấy, đây là sản phẩm đang có nhu cầu lớn, nếu chất lượng đảm bảo thì hoàn toàn có thể chiếm lĩnh được lòng tin của người tiêu dùng. Đặc biệt, qua tư vấn của bạn bè, anh H đã dự liệu được những rủi ro, khó khăn tiềm ẩn để có giải pháp khắc phục. Trên cơ sở tìm hiểu và đánh giá này, anh H đã lên kế hoạch chi tiết việc bán hàng, tiếp thị, quảng cáo để quảng bá giới thiệu sản phẩn đến khách hàng. Sự cam kết của anh đối với việc cung cấp sản phẩm chất lượng cao và an toàn đã thu hút được người tiêu dùng. Chính các yếu tố này đã giúp anh H xây dựng thành công thương hiệu của mình trên địa bàn huyện X, anh dự định sẽ tiếp tục mở rộng các cửa hàng để hình thành chuỗi cửa hàng chất lượng cao.", "cauHoi": [{"question": "Nội dung nào dưới đây thể hiện việc xác định ý tưởng kinh doanh của anh H?", "choices": ["Đẩy mạnh quảng cáo sản phẩm.", "Xây dựng chuỗi cửa hàng.", "Mở cửa hàng chất lượng cao.", "Kinh doanh thực phẩm sạch."], "correctIndex": 3, "explain": "<b>Đáp án:</b> <b>D. Kinh doanh thực phẩm sạch.</b><br><b>Giải thích:</b><br><b>Ý tưởng kinh doanh</b> là điểm khởi đầu, câu trả lời cho câu hỏi: <i>&quot;Chúng ta định bán cái gì?&quot;</i>.<br>Trong đoạn văn, ngay từ dòng đầu tiên, mục tiêu cốt lõi của anh H là &quot;phân phối thực phẩm sạch&quot;. Các phương án A, B, C thực chất là các bước triển khai hoặc hình thức vận hành sau khi đã có ý tưởng."}, {"question": "Nội dung nào dưới không thể hiện việc phân tích các điều kiện thực hiện ý tưởng kinh doanh?", "choices": ["Cam kết với người tiêu dùng.", "Mở rộng quy mô cửa hàng.", "Sản phẩm có nhu cầu lớn.", "Quảng cáo giới thiệu sản phẩm."], "correctIndex": 1, "explain": "<b>Đáp án:</b> <b>B. Mở rộng quy mô cửa hàng.</b><br><b>Giải thích:</b><br><b>Phân tích các điều kiện</b> là việc đánh giá xem mình đang có gì và thị trường đang cần gì trước khi bắt tay vào làm (như: nhu cầu khách hàng, rủi ro, dự liệu khó khăn).<br>Việc <b>&quot;Mở rộng quy mô&quot;</b> là bước phát triển ở giai đoạn cuối, khi việc kinh doanh đã thành công và có nền tảng vững chắc. Nó thuộc về định hướng tương lai, không phải là bước &quot;phân tích điều kiện&quot; để bắt đầu."}, {"question": "Anh H đã xác định mục tiêu kinh doanh của mình đó là", "choices": ["sản phẩm đang có nhu cầu lớn.", "xây dựng chuỗi thực phẩm sạch.", "tiếp cận nhu cầu người tiêu dùng.", "quảng cáo giới thiệu sản phẩm."], "correctIndex": 1, "explain": "<b>Đáp án:</b> <b>B. Xây dựng chuỗi thực phẩm sạch.</b><br><b>Giải thích:</b><br><b>Mục tiêu kinh doanh</b> là cái đích mà người kinh doanh muốn đạt được (kết quả cuối cùng).<br>Anh H không chỉ muốn bán lẻ đơn thuần, mà ngay từ đầu kế hoạch của anh là &quot;xây dựng thành công <b>chuỗi</b> cửa hàng&quot;. Các phương án khác như quảng cáo (D) hay tìm hiểu nhu cầu (A, C) chỉ là phương tiện hoặc công cụ để giúp anh đạt được mục tiêu xây dựng chuỗi cửa hàng đó."}], "khongXaoTron": true}]};
